def drawn(config: settings, fixed_seed: int | None = None) -> list[str]:
    seen = []

    @config
    @given(cases())
    def record(case) -> None:
        seen.append(repr(case))

    if fixed_seed is not None:
        record = seed(fixed_seed)(record)
    record()
    return seen

